/* flies.js: a few calm Drosophila walking over the page.
 *
 * Sprite: img/fly-sprite.png (generated by design/make_fly_sprite.py)
 *   cells are 24x24 CSS px (drawn at 3x), fly faces up
 *   row 0  female body: stand | walk1-4 | groom-front | groom-hind
 *   row 1  male body:   same columns (smaller, dark abdomen tip)
 *   row 2  wings:       folded | flick-small | flick-wide | left-out | right-out
 * Each fly is two stacked layers (body + wings) so legs and wings animate independently.
 *
 * Behaviour (all timings in real time):
 *   - stop-start walking: short walks, pauses, grooming bouts (wings jitter only while grooming)
 *   - the cursor makes flies run away fast (no flying)
 *   - only males court, and only females. Males are weakly drawn to the nearest female from
 *     anywhere on screen, and strongly drawn to a female that is already being chased, so
 *     rival males pile into a chase.
 *   - a courted female runs continuously along a tortuous path, stopping only briefly;
 *     her suitors follow at the same speed, singing with the wing on her side extended.
 *     If a suitor is right behind her when she stops, he may mount her.
 *   - ants (ants.js) are avoided; an ant that reaches a fly turns it into food for the colony.
 */
(function () {
  'use strict';

  /* ═══════════════ PARAMETERS ═══════════════ */
  var NUM_FLIES        = 12;     /* 6 males + 6 females */
  var FLY_SIZE         = 0.64;   /* on-screen size relative to the 24px sprite cell (≈ ant size) */
  var MALE_SCALE       = 0.9;    /* males are ~10% smaller than females */
  var LAYER_OPACITY    = 0.45;

  var WALK_SPEED_MIN   = 16;     /* px / s */
  var WALK_SPEED_MAX   = 26;
  var WALK_MS          = [600, 2200];
  var PAUSE_MS         = [800, 3500];
  var GROOM_MS         = [1800, 4500];
  var MAX_TURN_RATE    = 110;    /* deg / s while wandering */
  var EDGE_MARGIN      = 50;     /* px from viewport edge where flies steer back inward */

  var MOUSE_DIST       = 80;     /* cursor proximity that startles a fly */
  var FLEE_SPEED       = 140;    /* px / s */
  var FLEE_MS          = [450, 800];

  var ATTRACT_TURN       = 30;   /* deg / s a walking male turns toward the nearest free female */
  var RIVAL_ATTRACT_TURN = 80;   /* ... and toward a female that is already being chased */
  var COURT_START_DIST   = 40;   /* px: a male starts courting a female this close */
  var RIVAL_JOIN_DIST    = 90;   /* px: a male joins an ongoing chase from this far */
  var COURT_MS           = [9000, 18000];  /* how long a male keeps trying before giving up */
  var COURT_FOLLOW       = 10;   /* px a suitor keeps behind/beside the female */
  var EVADE_SPEED_MULT   = 1.7;  /* courted females run this much faster than they walk */
  var EVADE_MS           = [2500, 7000];   /* continuous running between brief stops */
  var EVADE_TURN_RATE    = 260;  /* deg / s: how tortuous her path is */
  var STOP_MS            = [700, 1800];    /* her brief stops */
  var SUITOR_SPEED_MULT  = 1.15; /* suitors can go a little faster than she runs */
  var SONG_ON_MS         = [400, 1200];
  var SONG_OFF_MS        = [300, 800];
  var MOUNT_MIN_COURT_MS = 3000; /* a suitor must have courted this long before mounting */
  var MOUNT_CHANCE       = 0.4;  /* per stop, if a suitor is right behind her */
  var MOUNT_MS           = [8000, 14000];
  var MALE_REFRACTORY    = [5000, 9000];
  var MATED_REFRACTORY   = 25000;

  var ANT_AVOID_DIST     = 30;
  var ANT_ENCOUNTER_DIST = 12;
  var ANT_AVOID_BOOST    = 1.7;
  var FLY_FOOD_FREEZE_MS = 1600;
  var COLLISION_PAD      = 1.5;
  var MAX_PUSH_PER_FRAME = 0.6;  /* px: overlaps are resolved gradually, never in one jump */
  var CLIMB_SPEED        = 30;   /* px / s a male walks onto the female when mounting */
  /* ════════════════════════════════════════════ */

  var CELL = 24;                 /* sprite cell, CSS px */
  var BODY_LEN = 14.6 * FLY_SIZE;  /* approx. body length on screen, px */
  var SPRITE_URL = '/img/fly-sprite.png';
  var SHEET_W = CELL * 7, SHEET_H = CELL * 3;
  var BODY_COL = { stand: 0, walk: 1, groomFront: 5, groomHind: 6 };
  var WING_COL = { folded: 0, flickSmall: 1, flickWide: 2, leftOut: 3, rightOut: 4 };

  var insectWorld = window.__insectWorld = window.__insectWorld || {};
  insectWorld.pendingFlyFoods = insectWorld.pendingFlyFoods || [];

  var D2R = Math.PI / 180, R2D = 180 / Math.PI;
  function rnd(a, b) { return a + Math.random() * (b - a); }
  function rndRange(r) { return rnd(r[0], r[1]); }
  function now() { return performance.now(); }
  function angleTo(x0, y0, x1, y1) { return Math.atan2(-(y1 - y0), x1 - x0) * R2D; } /* 0 = east, CCW, y up */
  function angDiff(a, b) { return ((a - b + 540) % 360) - 180; }                     /* signed a - b in (-180, 180] */
  function dist(x0, y0, x1, y1) { var dx = x1 - x0, dy = y1 - y0; return Math.sqrt(dx * dx + dy * dy); }
  function remove(arr, item) { var i = arr.indexOf(item); if (i >= 0) arr.splice(i, 1); }

  var mouseX = -9999, mouseY = -9999;
  window.addEventListener('mousemove', function (e) { mouseX = e.clientX; mouseY = e.clientY; }, { passive: true });
  /* forget the cursor when it leaves the page, or flies entering near where it left flee straight back out */
  function forgetCursor() { mouseX = -9999; mouseY = -9999; }
  document.addEventListener('mouseout', function (e) { if (!e.relatedTarget) forgetCursor(); });
  window.addEventListener('blur', forgetCursor);

  /* All flies live in one fixed layer, painted beneath page content (see styles.css). */
  var layer = document.createElement('div');
  layer.className = 'fly-layer';
  layer.setAttribute('aria-hidden', 'true');
  layer.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden;opacity:' + LAYER_OPACITY;

  function spriteDiv() {
    var d = document.createElement('div');
    d.style.cssText = 'position:absolute;left:0;top:0;width:' + CELL + 'px;height:' + CELL + 'px;' +
      'background:url(' + SPRITE_URL + ') no-repeat;background-size:' + SHEET_W + 'px ' + SHEET_H + 'px';
    return d;
  }

  var flies = [];

  function pickSex() {
    var males = 0, females = 0;
    for (var i = 0; i < flies.length; i++) { if (flies[i].sex === 'male') males++; else females++; }
    var maleTarget = Math.floor(NUM_FLIES / 2);
    if (males >= maleTarget) return 'female';
    if (females >= NUM_FLIES - maleTarget) return 'male';
    return males <= females ? 'male' : 'female';
  }

  /* ─────────────────────────── Fly ─────────────────────────── */
  function Fly() {
    this.sex = pickSex();
    this.scale = FLY_SIZE * (this.sex === 'male' ? MALE_SCALE : 1);
    this.radius = BODY_LEN * 0.4 * (this.sex === 'male' ? MALE_SCALE : 1);
    this.speed = rnd(WALK_SPEED_MIN, WALK_SPEED_MAX);

    this.el = document.createElement('div');
    this.el.style.cssText = 'position:absolute;left:0;top:0;width:' + CELL + 'px;height:' + CELL + 'px;will-change:transform';
    this.body = spriteDiv();
    this.wings = spriteDiv();
    this.el.appendChild(this.body);
    this.el.appendChild(this.wings);
    layer.appendChild(this.el);

    this.dead = false;
    this.frozen = false;
    this.state = 'walk';
    this.stateEnd = 0;
    this.turnRate = 0;
    this.turnPickAt = 0;
    this.gaitPhase = 0;          /* distance walked, drives the leg cycle */
    this.bodyPose = 'stand';
    this.wingPose = 'folded';
    this.refractoryUntil = 0;

    /* female courtship bookkeeping */
    this.suitors = [];           /* males currently chasing her */
    this.mate = null;            /* male mounted on her */
    this.mountRolled = false;
    /* male courtship bookkeeping */
    this.partner = null;         /* female he is chasing / mounted on */
    this.courtStart = 0;
    this.songOn = false;
    this.songSwitchAt = 0;

    this.enterFromEdge();
    this.setState('walk', rndRange(WALK_MS) + 1500);   /* walk well onto the screen first */
  }

  Fly.prototype.enterFromEdge = function () {
    var W = window.innerWidth, H = window.innerHeight, side = Math.floor(Math.random() * 4);
    if (side === 0)      { this.x = rnd(0, W); this.y = -CELL; }
    else if (side === 1) { this.x = W + CELL;  this.y = rnd(0, H); }
    else if (side === 2) { this.x = rnd(0, W); this.y = H + CELL; }
    else                 { this.x = -CELL;     this.y = rnd(0, H); }
    this.angle = angleTo(this.x, this.y, W / 2 + rnd(-W / 4, W / 4), H / 2 + rnd(-H / 4, H / 4));
  };

  Fly.prototype.setState = function (state, duration) {
    var t = now();
    this.state = state;
    this.stateEnd = t + duration;
    if (state === 'groom') {
      this.groomStart = t;
      this.groomNextFlick = t + rnd(200, 600);
      this.groomFlickEnd = 0;
      this.groomToggleAt = t;
      this.groomAlt = false;
    }
    if (state === 'stop') this.mountRolled = false;
  };

  Fly.prototype.nextIdleState = function () {
    var r = Math.random();
    if (this.state === 'walk')       this.setState(r < 0.62 ? 'pause' : 'groom', rndRange(r < 0.62 ? PAUSE_MS : GROOM_MS));
    else if (this.state === 'pause') this.setState(r < 0.8 ? 'walk' : 'groom', rndRange(r < 0.8 ? WALK_MS : GROOM_MS));
    else                             this.setState('walk', rndRange(WALK_MS));
  };

  /* ── courtship relationships ── */
  Fly.prototype.isCourtable = function (t) {
    return this.sex === 'female' && !this.dead && !this.frozen && !this.mate &&
      this.state !== 'flee' && t >= this.refractoryUntil;
  };

  Fly.prototype.joinCourtship = function (f) {        /* male */
    this.partner = f;
    this.courtStart = now();
    this.songOn = false;
    this.songSwitchAt = this.courtStart + rnd(200, 500);
    this.setState('court', rndRange(COURT_MS));
    f.suitors.push(this);
    if (f.suitors.length === 1) f.setState('evade', rndRange(EVADE_MS));   /* first suitor: she starts running */
  };

  Fly.prototype.endCourtship = function (refractoryMs) {   /* male */
    var f = this.partner, t = now();
    if (f) {
      remove(f.suitors, this);
      if (f.mate === this) {
        f.mate = null;
        f.refractoryUntil = t + (refractoryMs === MATED_REFRACTORY ? MATED_REFRACTORY : 4000);
        f.setState('walk', rndRange(WALK_MS));
      } else if (!f.suitors.length && (f.state === 'evade' || f.state === 'stop')) {
        f.setState('walk', rndRange(WALK_MS));
      }
    }
    this.partner = null;
    this.songOn = false;
    this.wingPose = 'folded';
    this.refractoryUntil = t + refractoryMs;
    if (this.state === 'court' || this.state === 'mounting') this.setState('walk', rndRange(WALK_MS));
  };

  Fly.prototype.dropAllCourtship = function (refractoryMs) {
    if (this.sex === 'male') { if (this.partner) this.endCourtship(refractoryMs); return; }
    if (this.mate) this.mate.endCourtship(refractoryMs);
    var s = this.suitors.slice();
    for (var i = 0; i < s.length; i++) s[i].endCourtship(refractoryMs);
  };

  Fly.prototype.startFlee = function (fromX, fromY) {
    this.dropAllCourtship(rndRange(MALE_REFRACTORY));
    this.angle = angleTo(fromX, fromY, this.x, this.y) + rnd(-25, 25);
    this.wingPose = 'folded';
    this.setState('flee', rndRange(FLEE_MS));
  };

  Fly.prototype.freezeForFood = function (ant) {
    if (this.dead || this.frozen) return false;
    var t = now();
    this.dropAllCourtship(0);
    this.frozen = true;
    this.state = 'frozen';
    this.stateEnd = t + FLY_FOOD_FREEZE_MS;
    this.bodyPose = 'stand';
    this.wingPose = 'folded';
    insectWorld.pendingFlyFoods.push({
      x: this.x, y: this.y, createdAt: t, expiresAt: t + FLY_FOOD_FREEZE_MS,
      antX: ant ? ant.x : null, antY: ant ? ant.y : null, claimed: false
    });
    return true;
  };

  Fly.prototype.retire = function (minDelay, maxDelay) {
    this.dropAllCourtship(0);
    this.dead = true;
    if (this.el.parentNode) this.el.parentNode.removeChild(this.el);
    setTimeout(function () { flies.push(new Fly()); }, rnd(minDelay, maxDelay));
  };

  /* ── movement ── */
  Fly.prototype.steerFromEdges = function (s) {
    var W = window.innerWidth, H = window.innerHeight;
    if (this.x < EDGE_MARGIN || this.x > W - EDGE_MARGIN || this.y < EDGE_MARGIN || this.y > H - EDGE_MARGIN) {
      var inward = angleTo(this.x, this.y, W / 2, H / 2);
      this.angle += Math.max(-1, Math.min(1, angDiff(inward, this.angle) / 30)) * 200 * s;
    }
  };

  /* mode: 'wander' (gentle), 'tortuous' (courted female), or 'straight' (heading set by caller) */
  Fly.prototype.walk = function (dt, speed, mode) {
    var s = dt / 1000, t = now();
    var f60 = s * 60, rootF60 = Math.sqrt(f60);   /* per-frame noise scaled so behaviour is the same at 60 or 120 Hz */
    if (mode === 'wander') {
      this.turnRate += rnd(-1, 1) * 10 * rootF60;
      this.turnRate = Math.max(-MAX_TURN_RATE, Math.min(MAX_TURN_RATE, this.turnRate * Math.pow(0.97, f60)));
      this.angle += this.turnRate * s;
      this.steerFromEdges(s);
    } else if (mode === 'tortuous') {
      if (t >= this.turnPickAt) {
        this.turnRate = rnd(-EVADE_TURN_RATE, EVADE_TURN_RATE);
        this.turnPickAt = t + rnd(150, 500);
      }
      this.angle += this.turnRate * s + rnd(-4, 4) * rootF60;
      this.steerFromEdges(s);
    }
    var a = this.angle * D2R, step = speed * s;
    this.x += Math.cos(a) * step;
    this.y -= Math.sin(a) * step;
    this.gaitPhase += step;
    this.bodyPose = 'walk';
  };

  Fly.prototype.turnToward = function (targetAngle, maxDegPerSec, dt) {
    var d = angDiff(targetAngle, this.angle), m = maxDegPerSec * dt / 1000;
    this.angle += Math.max(-m, Math.min(m, d));
  };

  /* The female a male is drawn to: chased females count as "closer" (rivals pile in). */
  Fly.prototype.mostAttractiveFemale = function (t) {
    var best = null, bestScore = Infinity;
    for (var i = 0; i < flies.length; i++) {
      var f = flies[i];
      if (f === this || !f.isCourtable(t)) continue;
      var d = dist(this.x, this.y, f.x, f.y);
      var score = f.suitors.length ? d * 0.4 : d;
      if (score < bestScore) { best = f; bestScore = score; }
    }
    return best ? { fly: best, d: dist(this.x, this.y, best.x, best.y) } : null;
  };

  /* ── per-frame update ── */
  Fly.prototype.tick = function (dt) {
    if (this.dead) return;
    var t = now(), W = window.innerWidth, H = window.innerHeight;

    if (this.frozen) {
      if (t >= this.stateEnd) this.retire(2000, 6000);
      this.draw();
      return;
    }

    /* ants: a forager that reaches a fly claims it as food; otherwise note the nearest */
    var ants = insectWorld.getAntStates ? insectWorld.getAntStates() : [];
    var nearAnt = null, nearAntD = Infinity;
    for (var i = 0; i < ants.length; i++) {
      var ad = dist(this.x, this.y, ants[i].x, ants[i].y);
      if (ants[i].canClaimFood && ad < ANT_ENCOUNTER_DIST && this.state !== 'flee') {
        this.freezeForFood(ants[i]);
        this.draw();
        return;
      }
      if (ad < nearAntD) { nearAnt = ants[i]; nearAntD = ad; }
    }

    /* cursor: run away fast */
    if (this.state !== 'flee' && dist(this.x, this.y, mouseX, mouseY) < MOUSE_DIST) this.startFlee(mouseX, mouseY);

    if (this.state === 'flee') {
      this.angle += rnd(-12, 12) * Math.sqrt(dt / 16.67);
      this.walk(dt, FLEE_SPEED, 'straight');
      this.wingPose = 'folded';
      if (this.x < -CELL * 2 || this.x > W + CELL * 2 || this.y < -CELL * 2 || this.y > H + CELL * 2) {
        this.retire(1500, 5000);   /* ran off screen: someone new wanders in later */
        return;
      }
      if (t >= this.stateEnd) this.setState('pause', rndRange(PAUSE_MS));
      this.draw();
      return;
    }

    /* mounted pairs stay put; the male carries the pair's timing */
    if (this.state === 'mounted') { this.bodyPose = 'stand'; this.wingPose = 'folded'; this.draw(); return; }
    if (this.state === 'mounting') { this.tickMounting(dt, t); this.draw(); return; }

    /* ants nearby: veer away and speed up (a chasing male gives up) */
    if (nearAnt && nearAntD < ANT_AVOID_DIST) {
      if (this.sex === 'male' && this.partner) this.endCourtship(rndRange(MALE_REFRACTORY));
      this.angle = angleTo(nearAnt.x, nearAnt.y, this.x, this.y);
      var running = this.state === 'evade' ? EVADE_SPEED_MULT : 1;
      if (this.state !== 'walk' && this.state !== 'evade') this.setState('walk', rndRange(WALK_MS));
      this.walk(dt, this.speed * running * ANT_AVOID_BOOST, 'straight');
      this.wingPose = 'folded';
      this.draw();
      return;
    }

    if (this.sex === 'male') {
      if (this.state === 'court') { this.tickCourtship(dt, t); this.draw(); return; }
      if (t >= this.refractoryUntil) {
        var nf = this.mostAttractiveFemale(t);
        if (nf) {
          var chased = nf.fly.suitors.length > 0;
          if (nf.d < (chased ? RIVAL_JOIN_DIST : COURT_START_DIST)) {
            this.joinCourtship(nf.fly);
            this.draw();
            return;
          }
          /* long-range attraction: drift toward her (much more strongly if she's being chased) */
          if (chased && this.state !== 'walk') this.setState('walk', rndRange(WALK_MS));
          if (this.state === 'walk') this.turnToward(angleTo(this.x, this.y, nf.fly.x, nf.fly.y), chased ? RIVAL_ATTRACT_TURN : ATTRACT_TURN, dt);
        }
      }
    } else if (this.suitors.length) {
      this.tickCourted(dt, t);
      this.draw();
      return;
    }

    /* ordinary stop-start life */
    if (t >= this.stateEnd) this.nextIdleState();
    if (this.state === 'walk') {
      this.walk(dt, this.speed, 'wander');
      this.wingPose = 'folded';
    } else if (this.state === 'pause') {
      this.bodyPose = 'stand';
      this.wingPose = 'folded';
    } else if (this.state === 'groom') {
      this.tickGroom(t);
    } else {
      this.setState('walk', rndRange(WALK_MS));
    }
    this.draw();
  };

  Fly.prototype.tickGroom = function (t) {
    /* first half: front legs rubbing; second half: hind legs sweeping the wings */
    var front = t < this.groomStart + (this.stateEnd - this.groomStart) / 2;
    if (t >= this.groomToggleAt) { this.groomAlt = !this.groomAlt; this.groomToggleAt = t + rnd(170, 260); }
    this.bodyPose = this.groomAlt ? (front ? 'groomFront' : 'groomHind') : 'stand';
    /* wings stay folded except for brief jittery flicks */
    if (t >= this.groomNextFlick) {
      this.wingPose = Math.random() < 0.6 ? 'flickSmall' : 'flickWide';
      this.groomFlickEnd = t + rnd(70, 150);
      this.groomNextFlick = t + rnd(300, 900);
    } else if (t >= this.groomFlickEnd) {
      this.wingPose = 'folded';
    }
  };

  /* Female being chased: run continuously along a tortuous path, with brief stops. */
  Fly.prototype.tickCourted = function (dt, t) {
    this.wingPose = 'folded';
    if (this.state !== 'evade' && this.state !== 'stop') this.setState('evade', rndRange(EVADE_MS));
    if (this.state === 'evade') {
      this.walk(dt, this.speed * EVADE_SPEED_MULT, 'tortuous');
      if (t >= this.stateEnd) this.setState('stop', rndRange(STOP_MS));
      return;
    }
    /* brief stop: the suitor right behind her may get to mount */
    this.bodyPose = 'stand';
    if (!this.mountRolled) {
      var best = null, bestD = Infinity;
      for (var i = 0; i < this.suitors.length; i++) {
        var m = this.suitors[i], d = dist(this.x, this.y, m.x, m.y);
        if (d < COURT_FOLLOW * 1.6 && t - m.courtStart >= MOUNT_MIN_COURT_MS && d < bestD) { best = m; bestD = d; }
      }
      if (best) {
        this.mountRolled = true;
        if (Math.random() < MOUNT_CHANCE) { this.startMount(best); return; }
      }
    }
    if (t >= this.stateEnd) this.setState('evade', rndRange(EVADE_MS));
  };

  Fly.prototype.startMount = function (male) {   /* female */
    var rivals = this.suitors.slice();
    for (var i = 0; i < rivals.length; i++) if (rivals[i] !== male) rivals[i].endCourtship(rndRange(MALE_REFRACTORY));
    this.mate = male;
    this.setState('mounted', 0);
    male.songOn = false;
    male.wingPose = 'folded';
    male.climbed = false;
    male.setState('mounting', rndRange(MOUNT_MS));
  };

  Fly.prototype.tickCourtship = function (dt, t) {   /* male */
    var f = this.partner;
    if (!f || f.dead || f.frozen || f.mate || f.suitors.indexOf(this) < 0) { this.endCourtship(rndRange(MALE_REFRACTORY)); return; }
    if (t >= this.stateEnd) { this.endCourtship(rndRange(MALE_REFRACTORY)); return; }   /* gave up */

    /* keep a spot just off her flank/rear, on whichever side we're already on */
    var rel = angDiff(angleTo(f.x, f.y, this.x, this.y), f.angle);
    var slot = f.angle + Math.max(110, Math.min(165, Math.abs(rel))) * (rel >= 0 ? 1 : -1);
    var tx = f.x + Math.cos(slot * D2R) * COURT_FOLLOW;
    var ty = f.y - Math.sin(slot * D2R) * COURT_FOLLOW;
    var gap = dist(this.x, this.y, tx, ty);
    var herSpeed = f.state === 'evade' ? f.speed * EVADE_SPEED_MULT : f.speed;
    if (gap > 1.5) {
      this.angle = angleTo(this.x, this.y, tx, ty);
      this.walk(dt, Math.min(Math.max(herSpeed, this.speed) * SUITOR_SPEED_MULT * (gap > 25 ? 1.3 : 1), gap * 6), 'straight');
    } else {
      this.bodyPose = 'stand';
    }
    if (gap <= 4) this.angle = angleTo(this.x, this.y, f.x, f.y);   /* face her */

    /* song: extend the wing on her side, in bouts */
    if (t >= this.songSwitchAt) {
      this.songOn = !this.songOn;
      this.songSwitchAt = t + rndRange(this.songOn ? SONG_ON_MS : SONG_OFF_MS);
    }
    if (this.songOn) {
      var side = angDiff(angleTo(this.x, this.y, f.x, f.y), this.angle);   /* > 0: she is to my left */
      this.wingPose = side >= 0 ? 'leftOut' : 'rightOut';
    } else {
      this.wingPose = 'folded';
    }
  };

  Fly.prototype.tickMounting = function (dt, t) {   /* male */
    var f = this.partner;
    if (!f || f.dead || f.frozen || f.mate !== this) { this.endCourtship(rndRange(MALE_REFRACTORY)); return; }
    /* walk up onto her back (slightly behind centre), turning to face the way she faces */
    var mx = f.x - Math.cos(f.angle * D2R) * BODY_LEN * 0.25;
    var my = f.y + Math.sin(f.angle * D2R) * BODY_LEN * 0.25;
    this.wingPose = 'folded';
    if (!this.climbed) {
      var d = dist(this.x, this.y, mx, my), step = Math.min(d, CLIMB_SPEED * dt / 1000);
      if (d > 0) {
        this.x += (mx - this.x) / d * step;
        this.y += (my - this.y) / d * step;
        this.gaitPhase += step;
      }
      this.turnToward(f.angle, 360, dt);
      this.bodyPose = 'walk';
      if (d - step < 0.3 && Math.abs(angDiff(f.angle, this.angle)) < 3) this.climbed = true;
      return;
    }
    this.angle = f.angle;
    this.x = mx;
    this.y = my;
    this.bodyPose = 'stand';
    if (t >= this.stateEnd) {
      this.endCourtship(MATED_REFRACTORY);
      this.angle += rnd(-60, 60);
    }
  };

  Fly.prototype.draw = function () {
    var row = this.sex === 'male' ? 1 : 0;
    var col = this.bodyPose === 'walk' ? BODY_COL.walk + (Math.floor(this.gaitPhase / (3.5 * FLY_SIZE)) % 4) : BODY_COL[this.bodyPose];
    this.body.style.backgroundPosition = (-col * CELL) + 'px ' + (-row * CELL) + 'px';
    this.wings.style.backgroundPosition = (-WING_COL[this.wingPose] * CELL) + 'px ' + (-2 * CELL) + 'px';
    this.el.style.zIndex = this.state === 'mounting' ? 2 : 1;
    this.el.style.transform =
      'translate(' + (this.x - CELL / 2).toFixed(1) + 'px,' + (this.y - CELL / 2).toFixed(1) + 'px)' +
      ' rotate(' + (90 - this.angle).toFixed(1) + 'deg) scale(' + this.scale + ')';
  };

  Fly.prototype.nudge = function (dx, dy) { this.x += dx; this.y += dy; };

  /* ─────────────────────────── world ─────────────────────────── */
  insectWorld.getFlyStates = function () {
    var live = [];
    for (var i = 0; i < flies.length; i++) {
      var f = flies[i];
      if (!f.dead) live.push({ x: f.x, y: f.y, angleDeg: f.angle, sex: f.sex, radius: f.radius, frozen: f.frozen, state: f.state, suitors: f.suitors.length });
    }
    return live;
  };

  function pinned(f) { return f.frozen || f.state === 'mounted' || f.state === 'mounting'; }

  function resolveCollisions() {
    for (var i = 0; i < flies.length; i++) {
      var a = flies[i];
      for (var j = i + 1; j < flies.length; j++) {
        var b = flies[j];
        if (a.mate === b || b.mate === a) continue;
        var dx = b.x - a.x, dy = b.y - a.y, d = Math.sqrt(dx * dx + dy * dy);
        var min = a.radius + b.radius + COLLISION_PAD;
        if (d >= min) continue;
        if (d === 0) { dx = rnd(-0.5, 0.5); dy = rnd(-0.5, 0.5); d = Math.sqrt(dx * dx + dy * dy) || 1; }
        var shareA = pinned(a) ? 0 : 0.5, shareB = pinned(b) ? 0 : 0.5;
        if (!shareA && !shareB) continue;
        if (!shareA) shareB = 1; else if (!shareB) shareA = 1;
        var o = Math.min(min - d, MAX_PUSH_PER_FRAME), nx = dx / d, ny = dy / d;
        a.nudge(-nx * o * shareA, -ny * o * shareA);
        b.nudge(nx * o * shareB, ny * o * shareB);
      }
    }
  }

  var lastT = null;
  function loop(t) {
    if (insectWorld.paused) { lastT = null; requestAnimationFrame(loop); return; }
    var dt = lastT === null ? 16 : Math.min(t - lastT, 100);
    lastT = t;
    flies = flies.filter(function (f) { return !f.dead; });
    for (var i = 0; i < flies.length; i++) flies[i].tick(dt);
    resolveCollisions();
    requestAnimationFrame(loop);
  }

  function init() {
    document.body.insertBefore(layer, document.body.firstChild);
    for (var i = 0; i < NUM_FLIES; i++) {
      setTimeout(function () { flies.push(new Fly()); }, rnd(300, 6000));
    }
    requestAnimationFrame(loop);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
